/bin/bash -lc "python3 - <<'PY'
import cv2, numpy as np
from PIL import Image
im=np.array(Image.open('first_frame.png')); g=cv2.cvtColor(im,cv2.COLOR_RGB2GRAY)
# threshold comps
for t in (25,35,45,55,65,75,85,95):
 m=(g<t).astype('uint8')
 n,lab,st,cent=cv2.connectedComponentsWithStats(m,8)
 inds=np.argsort(st[1:,4])[::-1][:12]+1
 print('\\nT',t)
 for i in inds:
  x,y,w,h,a=st[i]; cx,cy=cent[i];
  if a>50: print(f'a={a:6} box={x:4},{y:3},{w:3},{h:3} c={cx:.0f},{cy:.0f}')
# representative rgb and gray horizontal intervals under threshold near center
for y in range(100,681,20):
 row=g[y]; m=row<55
 runs=[]; s=None
 for x,v in enumerate(np.r_[m,False]):
  if v and s is None:s=x
  elif not v and s is not None:
   if x-s>=3:runs.append((s,x-1))
   s=None
 rr=[r for r in runs if r[1]>=400 and r[0]<=900]
 print(y, rr)
PY"
